INSERT INTO lessons VALUES('P1A-U02-L2',2,'course-targets-v2',1,'A',2,'This is和That is','{"id":"P1A-U02-L2","unitId":"P1A-U02","grade":1,"term":"A","order":6,"unitLesson":2,"unitNumber":2,"minutes":7,"title":"This is和That is","subtitle":"和家长把物品放近或放远，分别用This is和That is介绍。","topicIds":["grammar.be"],"vocabulary":[{"word":"this","meaning":"这个"},{"word":"that","meaning":"那个"},{"word":"ruler","meaning":"尺子"}],"task":"和家长把物品放近或放远，分别用This is和That is介绍。","unitTitle":"我的书包","releaseId":"course-targets-v2","cards":[{"title":"This is和That is","rule":"this指较近的一件东西，that指较远的一件东西。介绍一件东西用This is…或That is…，这里的is不变成are。","example":"This is my bag.","translation":"这是我的书包。"},{"title":"This is和That is","rule":"this指较近的一件东西，that指较远的一件东西。介绍一件东西用This is…或That is…，这里的is不变成are。","example":"That is a kite.","translation":"那是一个风筝。"},{"title":"This is和That is","rule":"this指较近的一件东西，that指较远的一件东西。介绍一件东西用This is…或That is…，这里的is不变成are。","example":"This is your cup.","translation":"这是你的杯子。"}],"itemCount":9,"version":2}');
INSERT INTO lessons VALUES('P1A-U02-L4',2,'course-targets-v2',1,'A',2,'我的小小书包展','{"id":"P1A-U02-L4","unitId":"P1A-U02","grade":1,"term":"A","order":8,"unitLesson":4,"unitNumber":2,"minutes":7,"title":"我的小小书包展","subtitle":"办一个一分钟书包展，用完整句子介绍两件物品。","topicIds":["grammar.articles","grammar.be"],"vocabulary":[{"word":"my","meaning":"我的"},{"word":"your","meaning":"你的"},{"word":"colour","meaning":"颜色"}],"task":"办一个一分钟书包展，用完整句子介绍两件物品。","unitTitle":"我的书包","releaseId":"course-targets-v2","cards":[{"title":"我的小小书包展","rule":"先说This is，再说a/an、颜色和物品。a/an看紧跟着它的单词开头的音：a blue bag、an orange bag。","example":"This is a black pen.","translation":"这是一支黑色的钢笔。"},{"title":"我的小小书包展","rule":"先说This is，再说a/an、颜色和物品。a/an看紧跟着它的单词开头的音：a blue bag、an orange bag。","example":"That is an orange box.","translation":"那是一个橙色的盒子。"},{"title":"我的小小书包展","rule":"先说This is，再说a/an、颜色和物品。a/an看紧跟着它的单词开头的音：a blue bag、an orange bag。","example":"My book is red.","translation":"我的书是红色的。"}],"itemCount":9,"version":2}');
INSERT INTO lessons VALUES('P3A-U02-L4',2,'course-targets-v2',3,'A',2,'朋友的一天小档案','{"id":"P3A-U02-L4","unitId":"P3A-U02","grade":3,"term":"A","order":8,"unitLesson":4,"unitNumber":2,"minutes":7,"title":"朋友的一天小档案","subtitle":"问一位家人一天中的两个活动时间，写下两句小记录。","topicIds":["tense.present-simple","grammar.prepositions"],"vocabulary":[{"word":"breakfast","meaning":"早饭"},{"word":"get up","meaning":"起床"},{"word":"at","meaning":"在（几点）"}],"task":"问一位家人一天中的两个活动时间，写下两句小记录。","unitTitle":"一天的节奏","releaseId":"course-targets-v2","cards":[{"title":"朋友的一天小档案","rule":"描述作息时，先说人物和活动，再说时间。整点前用at；问句里有Does时动词回原形。几点起床不是能力高低，没有统一优秀作息分数。","example":"Sam gets up at six.","translation":"Sam六点起床。"},{"title":"朋友的一天小档案","rule":"描述作息时，先说人物和活动，再说时间。整点前用at；问句里有Does时动词回原形。几点起床不是能力高低，没有统一优秀作息分数。","example":"Lily has breakfast at seven.","translation":"Lily七点吃早饭。"},{"title":"朋友的一天小档案","rule":"描述作息时，先说人物和活动，再说时间。整点前用at；问句里有Does时动词回原形。几点起床不是能力高低，没有统一优秀作息分数。","example":"Does Tom go to school at eight?","translation":"Tom八点去学校吗？"}],"itemCount":9,"version":2}');
INSERT INTO lessons VALUES('P5A-U02-L2',2,'course-targets-v2',5,'A',2,'频率词放在哪里','{"id":"P5A-U02-L2","unitId":"P5A-U02","grade":5,"term":"A","order":6,"unitLesson":2,"unitNumber":2,"minutes":7,"title":"频率词放在哪里","subtitle":"用一组be句和动作句描述习惯，观察频率词的位置。","topicIds":["grammar.frequency","grammar.be"],"vocabulary":[{"word":"often","meaning":"经常"},{"word":"ready","meaning":"准备好的"},{"word":"player","meaning":"运动员；队员"}],"task":"用一组be句和动作句描述习惯，观察频率词的位置。","unitTitle":"运动与健康","releaseId":"course-targets-v2","cards":[{"title":"频率词放在哪里","rule":"频率副词通常放在be动词后、实义动词前：is often tired，但often plays。通常位置不等于唯一可能位置，本课练中性表达。","example":"Mia is often busy.","translation":"Mia经常很忙。"},{"title":"频率词放在哪里","rule":"频率副词通常放在be动词后、实义动词前：is often tired，但often plays。通常位置不等于唯一可能位置，本课练中性表达。","example":"They are usually helpful.","translation":"他们通常很乐于助人。"},{"title":"频率词放在哪里","rule":"频率副词通常放在be动词后、实义动词前：is often tired，但often plays。通常位置不等于唯一可能位置，本课练中性表达。","example":"Tom often practises tennis.","translation":"Tom经常练网球。"}],"itemCount":9,"version":2}');
INSERT INTO lessons VALUES('P5A-U02-L4',2,'course-targets-v2',5,'A',2,'读一张习惯调查表','{"id":"P5A-U02-L4","unitId":"P5A-U02","grade":5,"term":"A","order":8,"unitLesson":4,"unitNumber":2,"minutes":7,"title":"读一张习惯调查表","subtitle":"看一位家人的习惯记录，先复述事实，再给一条可选择的温和建议。","topicIds":["grammar.frequency","grammar.modals"],"vocabulary":[{"word":"habit","meaning":"习惯"},{"word":"survey","meaning":"调查"},{"word":"break","meaning":"休息"}],"task":"看一位家人的习惯记录，先复述事实，再给一条可选择的温和建议。","unitTitle":"运动与健康","releaseId":"course-targets-v2","cards":[{"title":"读一张习惯调查表","rule":"读调查先分清“多常”和“多大程度”，再给温和建议。建议可以用could加动词原形；建议只是一个选择，对方可以决定是否采纳。","example":"Lily often walks with her family.","translation":"Lily经常和家人散步。"},{"title":"读一张习惯调查表","rule":"读调查先分清“多常”和“多大程度”，再给温和建议。建议可以用could加动词原形；建议只是一个选择，对方可以决定是否采纳。","example":"She is sometimes tired.","translation":"她有时感到累。"},{"title":"读一张习惯调查表","rule":"读调查先分清“多常”和“多大程度”，再给温和建议。建议可以用could加动词原形；建议只是一个选择，对方可以决定是否采纳。","example":"She could take a short break.","translation":"她可以稍作休息。"}],"itemCount":9,"version":2}');
INSERT INTO lessons VALUES('P6A-U02-L3',2,'course-targets-v2',6,'A',2,'经历和具体过去时间','{"id":"P6A-U02-L3","unitId":"P6A-U02","grade":6,"term":"A","order":7,"unitLesson":3,"unitNumber":2,"minutes":7,"title":"经历和具体过去时间","subtitle":"先问经历，再在对方愿意分享时用When did…?问具体时间。","topicIds":["tense.present-perfect","tense.past-simple"],"vocabulary":[{"word":"when","meaning":"什么时候"},{"word":"last","meaning":"上一个的"},{"word":"yesterday","meaning":"昨天"}],"task":"先问经历，再在对方愿意分享时用When did…?问具体时间。","unitTitle":"难忘的经历","releaseId":"course-targets-v2","cards":[{"title":"经历和具体过去时间","rule":"Have you ever…?问到现在的经历。追问具体什么时候发生，则用一般过去时，如I saw it yesterday。这里学习两种时间视角，不靠一个时间词机械猜答案。","example":"Have you ever been to a zoo?","translation":"你曾去过动物园吗？"},{"title":"经历和具体过去时间","rule":"Have you ever…?问到现在的经历。追问具体什么时候发生，则用一般过去时，如I saw it yesterday。这里学习两种时间视角，不靠一个时间词机械猜答案。","example":"I went there last Sunday.","translation":"我上周日去了那里。"},{"title":"经历和具体过去时间","rule":"Have you ever…?问到现在的经历。追问具体什么时候发生，则用一般过去时，如I saw it yesterday。这里学习两种时间视角，不靠一个时间词机械猜答案。","example":"When did you go?","translation":"你什么时候去的？"}],"itemCount":9,"version":2}');
INSERT INTO items VALUES('P1A-U02-L2.p1.choice',2,'P1A-U02-L2',2,'grammar.be.present','recognition','choice','{"id":"P1A-U02-L2.p1.choice","category":"grammar","title":"This is和That is","context":"介绍手边自己的尺子，填写be动词。","prompt":"This ___ my ruler.","type":"choice","choices":["is","am","are"],"gradeMin":1}','{"answers":["is"],"hint":"this指较近的一件东西，that指较远的一件东西。介绍一件东西用This is…或That is…，这里的is不变成are。","explanation":"This is my ruler. 这是我的尺子。 this指较近的一件东西，that指较远的一件东西。介绍一件东西用This is…或That is…，这里的is不变成are。","family":"fact-ecb4552f104bd137"}','published');
